class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        if not coins or not coins[0]:
            return 0

        m, n = len(coins), len(coins[0])
        NEG_INF = -10**18

        # prev_dp[k][j] stores the max profit at current row, column j with exactly k neutralizations used.
        prev_dp = [[NEG_INF] * n for _ in range(3)]

        # Base case for (0,0)
        start_val = coins[0][0]
        prev_dp[0][0] = start_val
        if start_val < 0:
            prev_dp[1][0] = 0
        else:
            prev_dp[1][0] = start_val
        prev_dp[2][0] = NEG_INF

        # Process first row (row 0), columns 1 to n-1
        for j in range(1, n):
            val = coins[0][j]
            for k in range(3):
                best = NEG_INF
                # from left: prev_dp[k][j-1] + val
                if prev_dp[k][j-1] != NEG_INF:
                    best = max(best, prev_dp[k][j-1] + val)
                # from left with neutralization: if k>=1, prev_dp[k-1][j-1] + (0 if val<0 else val)
                if k >= 1 and prev_dp[k-1][j-1] != NEG_INF:
                    neutralized_val = 0 if val < 0 else val
                    best = max(best, prev_dp[k-1][j-1] + neutralized_val)
                prev_dp[k][j] = best

        # Process subsequent rows
        for i in range(1, m):
            for j in range(n):
                val = coins[i][j]
                for k in range(3):
                    best = NEG_INF
                    # from top: prev_dp[k][j] (previous row, same column) + val
                    if prev_dp[k][j] != NEG_INF:
                        best = max(best, prev_dp[k][j] + val)
                    # from left: current row's j-1 (which is prev_dp[k][j-1] after updated in the current row's j-1 step) + val
                    if j > 0 and prev_dp[k][j-1] != NEG_INF:
                        best = max(best, prev_dp[k][j-1] + val)
                    # from top with neutralization: if k>=1, prev_dp[k-1][j] (previous row, same column) + (0 if val<0 else val)
                    if k >= 1 and prev_dp[k-1][j] != NEG_INF:
                        neutralized_val = 0 if val < 0 else val
                        best = max(best, prev_dp[k-1][j] + neutralized_val)
                    # from left with neutralization: if k>=1, current row's j-1 (prev_dp[k-1][j-1] after updated) + (0 if val<0 else val)
                    if k >= 1 and j > 0 and prev_dp[k-1][j-1] != NEG_INF:
                        neutralized_val = 0 if val < 0 else val
                        best = max(best, prev_dp[k-1][j-1] + neutralized_val)
                    prev_dp[k][j] = best

        # Result is max of the last column
        return max(prev_dp[k][n-1] for k in range(3))

